(async()=>{'use strict';const d=await fetch('data/account-dashboard-20261030.json?v=20261111-v64').then(r=>r.json());const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const max=Math.max(...d.tenure.months.map(r=>r.count));document.querySelector('#ygd-tenure-chart').innerHTML='<div class="tenure-months">'+d.tenure.months.map(r=>'<div><strong>'+r.count+'</strong><i style="height:'+Math.max(2,r.count/max*115)+'px"></i><span>'+r.month.slice(2)+'</span></div>').join('')+'</div>';document.querySelector('#ygd-formats').innerHTML=d.tenure.publish_time_bins.map(r=>'<div class="tenure-hour"><span>'+r.label+'</span><strong>'+r.value+'</strong></div>').join('');document.querySelector('#ygd-topics').innerHTML='<p>苏东坡、庄子、李白；从人物经历、经典文本到日常生活的问题。</p>';document.querySelector('#ygd-milestones').innerHTML=d.milestones.map(r=>'<article><b>'+r.date+'</b><strong>'+e(r.display)+'</strong><a href="'+e(r.url)+'" target="_blank" rel="noopener noreferrer">当期报道 ↗</a></article>').join('');await window.__m_yigongzi_date_filter_js.initDateFilters();})().catch(error=>console.error(error));
